<?php
declare(strict_types=1);
namespace EPejabat\Core;
final class Accounts {
    public const GENERIC='Jika maklumat sepadan, pautan pengesahan akan dihantar apabila penghantaran e-mel tersedia.';
    public static function throttle(\PDO $p,string $flow,string $email):void {
        $ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'cli');$account=hash('sha256',$email);$lock='ep_flow_'.substr(hash('sha256',(string)$p->query('SELECT DATABASE()')->fetchColumn()),0,48);
        if((int)Database::query($p,'SELECT GET_LOCK(?,5)',[$lock])->fetchColumn()!==1)throw new \RuntimeException('Sila cuba kemudian.');try{$count=(int)Database::query($p,'SELECT COUNT(*) FROM public_flow_attempts WHERE flow_key=? AND account_hash=? AND created_at>UTC_TIMESTAMP()-INTERVAL 15 MINUTE',[$flow,$account])->fetchColumn();$ipCount=(int)Database::query($p,'SELECT COUNT(*) FROM public_flow_attempts WHERE flow_key=? AND ip_hash=? AND created_at>UTC_TIMESTAMP()-INTERVAL 15 MINUTE',[$flow,$ip])->fetchColumn();if($count>=5||$ipCount>=20)throw new \RuntimeException('Terlalu banyak cubaan. Cuba selepas 15 minit.');Database::query($p,'INSERT INTO public_flow_attempts(flow_key,ip_hash,account_hash) VALUES(?,?,?)',[$flow,$ip,$account]);}finally{Database::query($p,'SELECT RELEASE_LOCK(?)',[$lock]);}
    }
    public static function issue(\PDO $p,string $purpose,string $email,?int $staff=null,?int $user=null,?int $request=null):void {
        // Invalidate earlier pending tokens of the same subject/purpose.
        Database::query($p,'UPDATE account_tokens SET used_at=UTC_TIMESTAMP() WHERE purpose=? AND (email=? OR (? IS NOT NULL AND user_id=?)) AND used_at IS NULL',[$purpose,$email,$user,$user]);$token=bin2hex(random_bytes(32));$expires=gmdate('Y-m-d H:i:s',time()+3600);Database::query($p,'INSERT INTO account_tokens(token_hash,purpose,staff_identity_id,user_id,request_id,email,expires_at) VALUES(?,?,?,?,?,?,?)',[hash('sha256',$token),$purpose,$staff,$user,$request,$email,$expires]);$invitation=(int)$p->lastInsertId();$url=self::origin().'/activate?token='.$token;$delivery=Notifications::enqueue($p,$email,$purpose==='reset'?'reset':($purpose==='correction'?'correction':'activation'),['url'=>$url,'expires_at'=>$expires,'context'=>$purpose==='claim'?($request?'approved_staff_invitation':'staff_invitation'):'account_verification']);if($purpose==='claim'&&$staff){$org=Database::query($p,'SELECT organisation_id FROM staff_profiles WHERE staff_identity_id=?',[$staff])->fetchColumn();Audit::record($p,'account.invitation_queued',null,$org?(int)$org:null,(string)$staff,'core',null,null,['invitation_id'=>$invitation,'delivery_id'=>$delivery,'expires_at'=>$expires]);}
    }
    public static function origin():string {$c=require APP_ROOT.'/config/app.php';$d=is_file(APP_ROOT.'/config/deployment.php')?require APP_ROOT.'/config/deployment.php':[];$url=$d['app_url']??$c['app_url'];if(($c['environment']??'')!=='local'&&$url==='https://epejabat.net')$url='https://pkdkb.epejabat.net';$parts=parse_url($url);if(!$parts||!isset($parts['host'])||!in_array($parts['scheme']??'',['http','https'],true)||isset($parts['user'])||isset($parts['pass'])||isset($parts['query'])||isset($parts['fragment'])||(($c['environment']??'')!=='local'&&!empty($parts['path']))||(($c['environment']??'')!=='local'&&$parts['scheme']!=='https'))throw new \RuntimeException('Origin tidak sah.');return $url;}
    public static function claim(\PDO $p,string $email,string $name):string {
        $email=Core::email($email);$name=Core::text($name);self::throttle($p,'claim',$email);Core::tx($p,function()use($p,$email,$name){$r=Database::query($p,"SELECT s.staff_identity_id,s.full_name FROM staff_profiles s JOIN staff_registry r ON r.staff_identity_id=s.staff_identity_id LEFT JOIN users u ON u.staff_identity_id=s.staff_identity_id WHERE s.official_email=? AND r.status='PRE_VERIFIED' AND u.id IS NULL FOR UPDATE",[$email])->fetch();if($r&&mb_strtolower(trim($r['full_name']))===mb_strtolower(trim($name)))self::issue($p,'claim',$email,(int)$r['staff_identity_id']);});return self::GENERIC;
    }
    public static function invite(\PDO $p,int $actor,int $staff,string $reason='Admin invitation'):void {
        self::throttle($p,'staff_invite','actor:'.$actor.':staff:'.$staff);
        Core::tx($p,function()use($p,$actor,$staff,$reason){$r=Database::query($p,"SELECT s.*,r.status FROM staff_profiles s JOIN staff_registry r ON r.staff_identity_id=s.staff_identity_id WHERE s.staff_identity_id=? FOR UPDATE",[$staff])->fetch();if(!$r)throw new \RuntimeException('Registry tidak tersedia.');Authorization::require($p,$actor,'core.staff.manage',(int)$r['organisation_id']);if($r['status']!=='PRE_VERIFIED'||Database::query($p,'SELECT 1 FROM users WHERE staff_identity_id=? OR email=?',[$staff,$r['official_email']])->fetchColumn())throw new \RuntimeException('Akaun sudah wujud atau registry tidak layak.');if(!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$r['organisation_id']])->fetchColumn())throw new \RuntimeException('Organisasi tidak aktif.');$req=Database::query($p,"SELECT id FROM registration_requests WHERE email=? AND request_kind='registration' AND status='APPROVED' AND organisation_id=? ORDER BY id DESC LIMIT 1",[$r['official_email'],$r['organisation_id']])->fetchColumn();self::issue($p,'claim',$r['official_email'],$staff,null,$req?(int)$req:null);Audit::record($p,'account.invitation_requested',$actor,(int)$r['organisation_id'],(string)$staff,'core',Core::text($reason,500));});
    }
    public static function invitationStatus(\PDO $p,int $actor,int $staff):array {
        $r=Database::query($p,'SELECT s.official_email,s.organisation_id,u.id AS user_id,u.is_active FROM staff_profiles s LEFT JOIN users u ON u.staff_identity_id=s.staff_identity_id WHERE s.staff_identity_id=?',[$staff])->fetch();if(!$r)throw new \RuntimeException('Registry tidak tersedia.');Authorization::require($p,$actor,'core.staff.manage',(int)$r['organisation_id']);if($r['user_id'])return ['delivery'=>'—','invitation'=>$r['is_active']?'ACCOUNT ACTIVATED':'ACCOUNT INACTIVE'];$a=Database::query($p,"SELECT * FROM audit_logs WHERE event='account.invitation_queued' AND subject=? ORDER BY id DESC LIMIT 1",[(string)$staff])->fetch();if(!$a||!Audit::valid($a))return ['delivery'=>'NOT RECORDED','invitation'=>'NOT INVITED / LEGACY'];$v=json_decode($a['after_json'],true);$t=Database::query($p,"SELECT used_at,expires_at,expires_at<=UTC_TIMESTAMP() AS expired FROM account_tokens WHERE id=? AND staff_identity_id=? AND email=? AND purpose='claim'",[$v['invitation_id']??0,$staff,$r['official_email']])->fetch();$d=Database::query($p,'SELECT status,attempts FROM notification_deliveries WHERE id=? AND email=?',[$v['delivery_id']??0,$r['official_email']])->fetch();$delivery=match($d['status']??''){ 'SENT'=>'SMTP ACCEPTED','FAILED'=>'FAILED DELIVERY','QUEUED'=>($d['attempts']?'QUEUED / RETRY':'INVITATION QUEUED'),default=>'NOT RECORDED'};return ['delivery'=>$delivery,'invitation'=>!$t?'INVALIDATED':($t['used_at']?'INVALIDATED':($t['expired']?'INVITATION EXPIRED':'INVITATION PENDING'))];
    }
    public static function resetRequest(\PDO $p,string $email):string {$email=Core::email($email);self::throttle($p,'reset',$email);Core::tx($p,function()use($p,$email){$u=Database::query($p,'SELECT id,staff_identity_id FROM users WHERE email=? AND is_active=1',[$email])->fetch();if($u)self::issue($p,'reset',$email,(int)$u['staff_identity_id'],(int)$u['id']);});return self::GENERIC;}
    public static function request(\PDO $p,array $d,?int $actor=null):string {
        if(RegistrationMaster::ready($p))return SmartRegistration::request($p,$d,$actor);
        $email=Core::email($d['email']??'');$name=Core::text($d['full_name']??'');$org=Core::id($d['organisation_id']??'');self::throttle($p,'registration',$email);if(!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$org])->fetchColumn())throw new \InvalidArgumentException('Organisasi tidak sah.');$prof=MasterData::validate($p,Core::id($d['profession_id']??null,true),'profession');Core::tx($p,function()use($p,$email,$name,$org,$prof){if(Database::query($p,'SELECT 1 FROM staff_profiles WHERE official_email=?',[$email])->fetchColumn()||Database::query($p,"SELECT 1 FROM registration_requests WHERE email=? AND status IN ('PENDING_VERIFICATION','REQUEST_CORRECTION','APPROVED')",[$email])->fetchColumn())return;Database::query($p,'INSERT INTO registration_requests(full_name,email,organisation_id,profession_id) VALUES(?,?,?,?)',[$name,$email,$org,$prof]);$id=(int)$p->lastInsertId();self::notifyReviewers($p,$org,$id);Audit::record($p,'registration.requested',null,$org,(string)$id);});return 'Permohonan diterima untuk semakan jika maklumat layak. Permohonan tidak memberikan akses dalaman.';
    }
    public static function notifyReviewers(\PDO $p,int $org,int $id):void {
        $users=Database::query($p,"SELECT DISTINCT a.user_id FROM user_role_assignments a JOIN role_permissions rp ON rp.role_id=a.role_id JOIN permissions pp ON pp.id=rp.permission_id JOIN users u ON u.id=a.user_id WHERE pp.code='core.registrations.review' AND u.is_active=1")->fetchAll();$local=[];$fallback=[];
        foreach($users as $u)if(Authorization::allowed($p,(int)$u['user_id'],'core.registrations.review',$org)){ $exact=Database::query($p,"SELECT 1 FROM user_role_assignments a JOIN organisations o ON o.id=a.organisation_id JOIN organisation_hierarchy h ON h.ancestor_id=o.id WHERE a.user_id=? AND o.type IN ('clinic','facility','unit') AND h.descendant_id=?",[$u['user_id'],$org])->fetchColumn();if($exact)$local[]=(int)$u['user_id'];else$fallback[]=(int)$u['user_id'];}
        foreach($local?:$fallback as $u){Notifications::inApp($p,$u,'Permohonan staf menunggu semakan','Permohonan #'.$id.' memerlukan tindakan.');$email=Database::query($p,'SELECT email FROM users WHERE id=?',[$u])->fetchColumn();Notifications::enqueue($p,$email,'system',['message'=>'Permohonan staf #'.$id.' menunggu semakan. Buka '.self::origin().'/registrations']);}
    }
    public static function review(\PDO $p,int $actor,int $id,string $decision,string $reason):void {
        if(RegistrationMaster::ready($p)){SmartRegistration::review($p,$actor,$id,$decision,$reason);return;}
        if(!in_array($decision,['APPROVED','REJECTED','REQUEST_CORRECTION'],true))throw new \InvalidArgumentException('Keputusan tidak sah.');$reason=Core::text($reason,500);Core::tx($p,function()use($p,$actor,$id,$decision,$reason){$r=Database::query($p,'SELECT * FROM registration_requests WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r||$r['status']!=='PENDING_VERIFICATION')throw new \RuntimeException('Permohonan tidak menunggu semakan.');$org=(int)$r['organisation_id'];Authorization::require($p,$actor,'core.registrations.review',$org);if($decision==='APPROVED'){$staff=Staff::preverify($p,$actor,['full_name'=>$r['full_name'],'official_email'=>$r['email'],'organisation_id'=>$org,'profession_id'=>$r['profession_id']]);self::issue($p,'claim',$r['email'],$staff,null,$id);}elseif($decision==='REQUEST_CORRECTION'){self::issue($p,'correction',$r['email'],null,null,$id);}else{Notifications::enqueue($p,$r['email'],'system',['message'=>'Permohonan anda tidak diluluskan. Sebab: '.$reason]);}Database::query($p,'UPDATE registration_requests SET status=?,reviewer_id=?,reason=? WHERE id=?',[$decision,$actor,$reason,$id]);Database::query($p,'INSERT INTO registration_review_history(request_id,actor_id,status,reason) VALUES(?,?,?,?)',[$id,$actor,$decision,$reason]);Audit::record($p,'registration.'.strtolower($decision),$actor,$org,(string)$id,'core',$reason,['status'=>$r['status']],['status'=>$decision]);});
    }
    public static function token(\PDO $p,string $token,bool $lock=false):array {
        if(!preg_match('/\A[a-f0-9]{64}\z/',$token))throw new \RuntimeException('Pautan tidak sah atau tamat tempoh.');$r=Database::query($p,'SELECT * FROM account_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>UTC_TIMESTAMP()'.($lock?' FOR UPDATE':''),[hash('sha256',$token)])->fetch();if(!$r)throw new \RuntimeException('Pautan tidak sah atau tamat tempoh.');return $r;
    }
    public static function consume(\PDO $p,string $token,string $password='',array $correction=[]):void {
        Core::tx($p,function()use($p,$token,$password,$correction){$t=self::token($p,$token,true);$org=null;$actor=null;
            if($t['purpose']==='registration_verify'){SmartRegistration::verifyEmail($p,$t);}
            elseif($t['purpose']==='correction'){$r=Database::query($p,'SELECT * FROM registration_requests WHERE id=? FOR UPDATE',[$t['request_id']])->fetch();if(!$r||$r['status']!=='REQUEST_CORRECTION')throw new \RuntimeException('Permohonan tidak boleh dipinda.');$name=Core::text($correction['full_name']??'');$prof=MasterData::validate($p,Core::id($correction['profession_id']??null,true),'profession');Database::query($p,"UPDATE registration_requests SET full_name=?,profession_id=?,status='PENDING_VERIFICATION',reviewer_id=NULL WHERE id=?",[$name,$prof,$r['id']]);Database::query($p,"INSERT INTO registration_review_history(request_id,status,reason) VALUES(?,'PENDING_VERIFICATION','Applicant corrected details via verified link')",[$r['id']]);$org=(int)$r['organisation_id'];self::notifyReviewers($p,$org,(int)$r['id']);}
            elseif($t['purpose']==='claim'){if($t['request_id']){if(!Database::query($p,"SELECT 1 FROM registration_requests WHERE id=? AND email=? AND request_kind='registration' AND status='APPROVED'",[$t['request_id'],$t['email']])->fetchColumn())throw new \RuntimeException('Approval identiti diperlukan.');}$password=Core::password($password);$s=Database::query($p,"SELECT s.*,r.status FROM staff_profiles s JOIN staff_registry r ON r.staff_identity_id=s.staff_identity_id WHERE s.staff_identity_id=? FOR UPDATE",[$t['staff_identity_id']])->fetch();if(!$s||$s['status']!=='PRE_VERIFIED'||$s['official_email']!==$t['email']||Database::query($p,'SELECT 1 FROM users WHERE staff_identity_id=?',[$s['staff_identity_id']])->fetchColumn())throw new \RuntimeException('Akaun sudah dituntut atau rekod telah berubah.');if(RegistrationMaster::profileReady($p)&&Database::query($p,"SELECT 1 FROM staff_email_contacts WHERE email=? AND staff_identity_id<>? AND status IN ('PENDING_ADMIN_APPROVAL','APPROVED')",[$t['email'],$s['staff_identity_id']])->fetchColumn())throw new \RuntimeException('Identiti/e-mel telah berubah.');$org=(int)$s['organisation_id'];if(!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$org])->fetchColumn())throw new \RuntimeException('Organisasi tidak aktif.');Database::query($p,'INSERT INTO users(staff_identity_id,username,email,password_hash,email_verified_at) VALUES(?,?,?,?,UTC_TIMESTAMP())',[$s['staff_identity_id'],'staff_'.$s['staff_identity_id'],$t['email'],password_hash($password,PASSWORD_DEFAULT)]);$actor=(int)$p->lastInsertId();if($t['request_id'])Database::query($p,'UPDATE registration_requests SET email_verified_at=COALESCE(email_verified_at,UTC_TIMESTAMP()) WHERE id=?',[$t['request_id']]);Database::query($p,"UPDATE staff_registry SET status='CLAIMED' WHERE staff_identity_id=?",[$s['staff_identity_id']]);Database::query($p,"INSERT INTO user_role_assignments(user_id,role_id,organisation_id,module_code) SELECT ?,id,?,'core' FROM roles WHERE code='staff'",[$actor,$org]);ModuleAccess::sync($p,$actor,$org,$actor);Notifications::inApp($p,$actor,'Akaun aktif','Akaun anda telah disahkan. Log masuk menggunakan e-mel utama.');}
            elseif($t['purpose']==='reset'){$password=Core::password($password);$u=Database::query($p,'SELECT * FROM users WHERE id=? AND email=? AND is_active=1 FOR UPDATE',[$t['user_id'],$t['email']])->fetch();if(!$u)throw new \RuntimeException('Pautan tidak sah.');$actor=(int)$u['id'];Database::query($p,'UPDATE users SET password_hash=?,email_verified_at=COALESCE(email_verified_at,UTC_TIMESTAMP()),credential_revision=credential_revision+1 WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$actor]);}
            elseif($t['purpose']==='emailchange'){if(RegistrationMaster::ready($p))throw new \RuntimeException('Pautan perubahan e-mel lama tidak boleh bypass approval. Mohon semula melalui Keselamatan Akaun.');$u=Database::query($p,'SELECT * FROM users WHERE id=? AND is_active=1 FOR UPDATE',[$t['user_id']])->fetch();if(!$u)throw new \RuntimeException('Pautan tidak sah.');$actor=(int)$u['id'];Database::query($p,'UPDATE users SET email=?,email_verified_at=UTC_TIMESTAMP(),credential_revision=credential_revision+1 WHERE id=?',[$t['email'],$actor]);Database::query($p,'UPDATE staff_profiles SET official_email=? WHERE staff_identity_id=?',[$t['email'],$u['staff_identity_id']]);}
            else throw new \RuntimeException('Tujuan token tidak sah.');Database::query($p,'UPDATE account_tokens SET used_at=UTC_TIMESTAMP() WHERE id=?',[$t['id']]);if($t['purpose']!=='correction')Database::query($p,'UPDATE account_tokens SET used_at=UTC_TIMESTAMP() WHERE purpose=? AND staff_identity_id=? AND used_at IS NULL',[$t['purpose'],$t['staff_identity_id']]);Audit::record($p,'account.'.$t['purpose'],$actor,$org,(string)($t['staff_identity_id']??$t['request_id']));});
    }
    public static function changePassword(\PDO $p,int $actor,string $current,string $new):void {Core::tx($p,function()use($p,$actor,$current,$new){$u=Database::query($p,'SELECT * FROM users WHERE id=? AND is_active=1 FOR UPDATE',[$actor])->fetch();if(!$u||!password_verify($current,$u['password_hash']))throw new \InvalidArgumentException('Kata laluan semasa tidak sah.');Database::query($p,'UPDATE users SET password_hash=?,credential_revision=credential_revision+1 WHERE id=?',[password_hash(Core::password($new),PASSWORD_DEFAULT),$actor]);Database::query($p,"UPDATE account_tokens SET used_at=UTC_TIMESTAMP() WHERE user_id=? AND purpose='reset' AND used_at IS NULL",[$actor]);Audit::record($p,'account.password_changed',$actor);});}
    public static function changeEmail(\PDO $p,int $actor,string $email,string $password):void {if(RegistrationMaster::ready($p)){SmartRegistration::changeEmail($p,$actor,$email,$password);return;}$email=Core::email($email);self::throttle($p,'emailchange',$email);Core::tx($p,function()use($p,$actor,$email,$password){$u=Database::query($p,'SELECT * FROM users WHERE id=? AND is_active=1 FOR UPDATE',[$actor])->fetch();if(!$u||!password_verify($password,$u['password_hash']))throw new \InvalidArgumentException('Kata laluan semasa tidak sah.');if(Database::query($p,'SELECT 1 FROM staff_profiles WHERE official_email=? AND staff_identity_id<>?',[$email,$u['staff_identity_id']])->fetchColumn()||Database::query($p,'SELECT 1 FROM users WHERE email=? AND id<>?',[$email,$actor])->fetchColumn())throw new \InvalidArgumentException('E-mel tidak tersedia.');self::issue($p,'emailchange',$email,(int)$u['staff_identity_id'],$actor);Audit::record($p,'account.email_change_requested',$actor);});}
}
